const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '支点' },
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '阻力臂' }
    ];
  },
  render: function (input, metrics) {
    var vb = (input && input.viewport) ? input.viewport : {};
    var W = (typeof vb.widthDu === 'number' && vb.widthDu > 0) ? vb.widthDu : 780;
    var H = (typeof vb.heightDu === 'number' && vb.heightDu > 0) ? vb.heightDu : 480;
    var s = Math.min(W / 780, H / 480);
    if (!isFinite(s) || s <= 0) { s = 1; }
    var ox = (W - 780 * s) / 2;
    var oy = (H - 480 * s) / 2;

    function X(v) { return ox + v * s; }
    function Y(v) { return oy + v * s; }
    function pt(p) { return [X(p[0]), Y(p[1])]; }

    var fontSize = 22 * s;
    if (fontSize < 9) { fontSize = 9; }

    function measure(i, text) {
      var m = metrics ? metrics[i] : null;
      var w = 0, h = 0;
      if (typeof m === 'number') { w = m; }
      else if (m && typeof m === 'object') {
        if (typeof m.width === 'number') { w = m.width; } else if (typeof m.w === 'number') { w = m.w; }
        if (typeof m.height === 'number') { h = m.height; } else if (typeof m.h === 'number') { h = m.h; }
      }
      if (!(w > 0)) { w = text.length * fontSize * 1.05; }
      if (!(h > 0)) { h = fontSize * 1.3; }
      return { w: w, h: h };
    }
    var mF = measure(0, '支点');
    var mP = measure(1, '动力臂');
    var mR = measure(2, '阻力臂');

    /* 设计坐标 780x480：A 动力作用点、F 支点、B 阻力作用点（棒端顶住石头）
       |AF| 水平 350，|FB| 水平 140 => 动力臂:阻力臂 = 5:2，三点共线 */
    var A = [130, 266];
    var F = [480, 336];
    var B = [620, 364];

    var dxAB = B[0] - A[0], dyAB = B[1] - A[1];
    var lenAB = Math.sqrt(dxAB * dxAB + dyAB * dyAB) || 1;
    var ux = dxAB / lenAB, uy = dyAB / lenAB;
    var nx = uy, ny = -ux;
    var OFF = 50;
    var A2 = [A[0] + nx * OFF, A[1] + ny * OFF];
    var F2 = [F[0] + nx * OFF, F[1] + ny * OFF];
    var B2 = [B[0] + nx * OFF, B[1] + ny * OFF];

    function headLines(tx, ty, dxn, dyn, len, ang) {
      var a = Math.atan2(dyn, dxn);
      var p1 = [tx - len * Math.cos(a - ang), ty - len * Math.sin(a - ang)];
      var p2 = [tx - len * Math.cos(a + ang), ty - len * Math.sin(a + ang)];
      return visualSdk.polyline([p1, [tx, ty], p2]);
    }
    function dimPath(p, q) {
      var ax = X(p[0]), ay = Y(p[1]);
      var bx = X(q[0]), by = Y(q[1]);
      var vx = bx - ax, vy = by - ay;
      var l = Math.sqrt(vx * vx + vy * vy) || 1;
      var ux2 = vx / l, uy2 = vy / l;
      var hl = Math.max(5, 11 * s);
      var line = visualSdk.polyline([[ax, ay], [bx, by]]);
      return line.concat(headLines(ax, ay, -ux2, -uy2, hl, 0.42), headLines(bx, by, ux2, uy2, hl, 0.42));
    }

    var pGround = visualSdk.polyline([pt([30, 400]), pt([750, 400])]);
    var pFulcrum = visualSdk.polyline([pt([480, 341]), pt([512, 400]), pt([450, 400]), pt([480, 341])]);
    var pBar = visualSdk.polyline([pt(A), pt(B)]);

    var rockPts = [[627, 400], [619, 372], [625, 342], [645, 320], [677, 312], [705, 326], [717, 356], [713, 384], [705, 400]];
    var rockConv = [];
    for (var i = 0; i < rockPts.length; i++) { rockConv.push(pt(rockPts[i])); }
    rockConv.push(pt(rockPts[0]));
    var pRock = visualSdk.polyline(rockConv);

    var pGuideA = visualSdk.polyline([pt(A), pt(A2)]);
    var pGuideF = visualSdk.polyline([pt(F), pt(F2)]);
    var pGuideB = visualSdk.polyline([pt(B), pt(B2)]);

    var pDimP = dimPath(A2, F2);
    var pDimR = dimPath(F2, B2);

    var paths = [
      { id: 'ground', commands: pGround },
      { id: 'fulcrum', commands: pFulcrum },
      { id: 'bar', commands: pBar },
      { id: 'rock', commands: pRock },
      { id: 'guidePower', commands: pGuideA },
      { id: 'guideFulcrum', commands: pGuideF },
      { id: 'guideResist', commands: pGuideB },
      { id: 'dimPower', commands: pDimP },
      { id: 'dimResist', commands: pDimR }
    ];

    var dashArr = [5 * s, 4 * s];
    var children = [
      { type: 'path', pathId: 'ground', stroke: '#37507a', strokeWidth: Math.max(1.5, 3 * s), fill: 'none' },
      { type: 'path', pathId: 'fulcrum', stroke: '#8a6a1f', strokeWidth: Math.max(1.2, 2.4 * s), fill: '#e8c76a' },
      { type: 'path', pathId: 'bar', stroke: '#4a5568', strokeWidth: Math.max(4, 10 * s), fill: 'none', lineCap: 'round', lineJoin: 'round' },
      { type: 'path', pathId: 'rock', stroke: '#5b6470', strokeWidth: Math.max(1.2, 2.4 * s), fill: '#b9c1cb' },
      { type: 'path', pathId: 'guidePower', stroke: '#d98880', strokeWidth: Math.max(1, 1.5 * s), fill: 'none', dash: dashArr },
      { type: 'path', pathId: 'guideFulcrum', stroke: '#d98880', strokeWidth: Math.max(1, 1.5 * s), fill: 'none', dash: dashArr },
      { type: 'path', pathId: 'guideResist', stroke: '#d98880', strokeWidth: Math.max(1, 1.5 * s), fill: 'none', dash: dashArr },
      { type: 'path', pathId: 'dimPower', stroke: '#c0392b', strokeWidth: Math.max(1.4, 2 * s), fill: 'none' },
      { type: 'path', pathId: 'dimResist', stroke: '#c0392b', strokeWidth: Math.max(1.4, 2 * s), fill: 'none' }
    ];

    var padF = Math.max(mF.h / 2, fontSize * 0.68);
    var padP = Math.max(mP.h / 2, fontSize * 0.68);
    var padR = Math.max(mR.h / 2, fontSize * 0.68);
    var midPx = (A2[0] + F2[0]) / 2, midPy = (A2[1] + F2[1]) / 2;
    var midRx = (F2[0] + B2[0]) / 2, midRy = (F2[1] + B2[1]) / 2;

    children.push({ type: 'label', x: X(481), y: Y(400) + 12 * s + padF, text: '支点', fontSize: fontSize, fill: '#1f3a5f', align: 'center', baseline: 'middle' });
    children.push({ type: 'label', x: X(midPx), y: Y(midPy) - 8 * s - padP, text: '动力臂', fontSize: fontSize, fill: '#a93226', align: 'center', baseline: 'middle' });
    children.push({ type: 'label', x: X(midRx), y: Y(midRy) - 8 * s - padR, text: '阻力臂', fontSize: fontSize, fill: '#a93226', align: 'center', baseline: 'middle' });

    return {
      schemaVersion: 1,
      sceneId: 'crowbar-rock-lever',
      revision: (input && input.revision != null) ? input.revision : 0,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
